I'm injecting Thomson Sampling into a bandit problem. I want to use bandits and thompson sampling to remove banners from a list in an ad campaign. for example, I have N banners and the probabilities of productivity drop when each of them is excluded. if a banner with the highest probability of poor performance is selected and we turn it off while receiving a reward, then at the next iteration we will not be able to turn it off. we will have fewer banners. please help me edit the code to take into account the possible reduction in the number of banners

class banditos():
    def __init__(self, arm_probs: list):
        self.arm_probs = arm_probs
        self.n_arms = len(self.arm_probs)
        self.alpha = np.ones(self.n_arms)
        self.beta = np.ones(self.n_arms)
        self.regret = 0

    def evaluate(true_prob: float):
        return 1 if np.random.uniform(0, 1, 1) <= true_prob else 0

    def update_prior(alpha: int, beta: int, reward: int, chosen_arm: int):
        alpha[chosen_arm] += reward
        beta[chosen_arm] += 1 - reward

        return alpha, beta

    def update_regret(regret: int, alpha: int, beta: int, reward: int, chosen_arm: int):
        arm_theta = [alpha / (alpha + beta) for alpha, beta in zip(alpha, beta)]

        if reward == 0:
            if arm_theta[chosen_arm] < max(arm_theta):
                regret += 1 

        return regret

