Can the below code generate prime numbers within the given range ?

def primes(lower, upper):
    """Returns all the prime numbers within the specified interval [lower, upper] as a list."""
    primes = []
    for num in range(lower, upper+1):
        if num < 1:
            continue
        is_prime = True
        for i in range(2, int(num**0.5)+1):
            if (num % i) == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

